changeSet.createProcedure:
CREATE OR REPLACE FUNCTION usermgmt_increment_version() RETURNS trigger AS $$
BEGIN
    UPDATE usermgmt_version SET version = version + 1 WHERE name = TG_ARGV[0];
    RETURN NULL;
END;
$$ LANGUAGE plpgsql;

changeSet.sql:
CREATE TRIGGER security_roles_version AFTER INSERT OR UPDATE OR DELETE OR TRUNCATE ON security_roles FOR EACH STATEMENT EXECUTE PROCEDURE usermgmt_increment_version('users');
CREATE TRIGGER users_version AFTER INSERT OR UPDATE OR DELETE OR TRUNCATE ON users FOR EACH STATEMENT EXECUTE PROCEDURE usermgmt_increment_version('users');
CREATE TRIGGER user_contacts_version AFTER INSERT OR UPDATE OR DELETE OR TRUNCATE ON user_contacts FOR EACH STATEMENT EXECUTE PROCEDURE usermgmt_increment_version('users');
CREATE TRIGGER user_duty_schedules_version AFTER INSERT OR UPDATE OR DELETE OR TRUNCATE ON user_duty_schedules FOR EACH STATEMENT EXECUTE PROCEDURE usermgmt_increment_version('users');
CREATE TRIGGER user_security_roles_version AFTER INSERT OR UPDATE OR DELETE OR TRUNCATE ON user_security_roles FOR EACH STATEMENT EXECUTE PROCEDURE usermgmt_increment_version('users');
CREATE TRIGGER groups_version AFTER INSERT OR UPDATE OR DELETE OR TRUNCATE ON groups FOR EACH STATEMENT EXECUTE PROCEDURE usermgmt_increment_version('groups');
CREATE TRIGGER group_members_version AFTER INSERT OR UPDATE OR DELETE OR TRUNCATE ON group_members FOR EACH STATEMENT EXECUTE PROCEDURE usermgmt_increment_version('groups');
CREATE TRIGGER group_duty_schedules_version AFTER INSERT OR UPDATE OR DELETE OR TRUNCATE ON group_duty_schedules FOR EACH STATEMENT EXECUTE PROCEDURE usermgmt_increment_version('groups');
CREATE TRIGGER oncall_roles_version AFTER INSERT OR UPDATE OR DELETE OR TRUNCATE ON oncall_roles FOR EACH STATEMENT EXECUTE PROCEDURE usermgmt_increment_version('groups');
CREATE TRIGGER oncall_schedules_version AFTER INSERT OR UPDATE OR DELETE OR TRUNCATE ON oncall_schedules FOR EACH STATEMENT EXECUTE PROCEDURE usermgmt_increment_version('groups');
CREATE TRIGGER oncall_schedule_times_version AFTER INSERT OR UPDATE OR DELETE OR TRUNCATE ON oncall_schedule_times FOR EACH STATEMENT EXECUTE PROCEDURE usermgmt_increment_version('groups');

rollback.sql:
DROP TRIGGER IF EXISTS security_roles_version ON security_roles;
DROP TRIGGER IF EXISTS users_version ON users;
DROP TRIGGER IF EXISTS user_contacts_version ON user_contacts;
DROP TRIGGER IF EXISTS user_duty_schedules_version ON user_duty_schedules;
DROP TRIGGER IF EXISTS user_security_roles_version ON user_security_roles;
DROP TRIGGER IF EXISTS groups_version ON groups;
DROP TRIGGER IF EXISTS group_members_version ON group_members;
DROP TRIGGER IF EXISTS group_duty_schedules_version ON group_duty_schedules;
DROP TRIGGER IF EXISTS oncall_roles_version ON oncall_roles;
DROP TRIGGER IF EXISTS oncall_schedules_version ON oncall_schedules;
DROP TRIGGER IF EXISTS oncall_schedule_times_version ON oncall_schedule_times;
DROP FUNCTION IF EXISTS usermgmt_increment_version();

changeSet.createProcedure:
-- BEFORE UPDATE of a parent row: a changed row gets a new version from the sequence. A statement that sets the
-- version to another value (the child triggers do, with version + 1) is a change, and the value it sets is replaced;
-- an UPDATE that changes nothing, including one that sets the version to its current value, keeps the version.
CREATE OR REPLACE FUNCTION usermgmt_bump_row_version() RETURNS trigger AS $$
BEGIN
    IF NEW.version IS DISTINCT FROM OLD.version
       OR (row_to_json(NEW)::jsonb - 'version') IS DISTINCT FROM (row_to_json(OLD)::jsonb - 'version') THEN
        NEW.version := nextval('usermgmt_row_version_seq');
    END IF;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

-- AFTER a change to a child row: bumps the parent. TG_ARGV[0] is the parent table, TG_ARGV[1] the FK column.
CREATE OR REPLACE FUNCTION usermgmt_bump_parent() RETURNS trigger AS $$
DECLARE
    new_id integer;
    old_id integer;
BEGIN
    -- an UPDATE that changes nothing is no change of the parent
    IF TG_OP = 'UPDATE' AND NEW IS NOT DISTINCT FROM OLD THEN
        RETURN NULL;
    END IF;
    IF TG_OP <> 'DELETE' THEN
        new_id := (to_jsonb(NEW) ->> TG_ARGV[1])::integer;
        EXECUTE format('UPDATE %I SET version = version + 1 WHERE id = $1', TG_ARGV[0]) USING new_id;
    END IF;
    IF TG_OP <> 'INSERT' THEN
        old_id := (to_jsonb(OLD) ->> TG_ARGV[1])::integer;
        IF old_id IS DISTINCT FROM new_id THEN
            EXECUTE format('UPDATE %I SET version = version + 1 WHERE id = $1', TG_ARGV[0]) USING old_id;
        END IF;
    END IF;
    RETURN NULL;
END;
$$ LANGUAGE plpgsql;

-- oncall_schedule_times reaches its on-call role through its schedule, which is gone when the role is deleted
CREATE OR REPLACE FUNCTION usermgmt_bump_oncall_role_of_time() RETURNS trigger AS $$
BEGIN
    -- an UPDATE that changes nothing is no change of the on-call role
    IF TG_OP = 'UPDATE' AND NEW IS NOT DISTINCT FROM OLD THEN
        RETURN NULL;
    END IF;
    IF TG_OP <> 'DELETE' THEN
        UPDATE oncall_roles SET version = version + 1
         WHERE id = (SELECT oncall_role_id FROM oncall_schedules WHERE id = NEW.schedule_id);
    END IF;
    IF TG_OP <> 'INSERT' AND (TG_OP = 'DELETE' OR OLD.schedule_id IS DISTINCT FROM NEW.schedule_id) THEN
        UPDATE oncall_roles SET version = version + 1
         WHERE id = (SELECT oncall_role_id FROM oncall_schedules WHERE id = OLD.schedule_id);
    END IF;
    RETURN NULL;
END;
$$ LANGUAGE plpgsql;

-- a renamed user: the groups it is a member of and the on-call roles it supervises or is scheduled in show the name
CREATE OR REPLACE FUNCTION usermgmt_bump_for_username() RETURNS trigger AS $$
BEGIN
    UPDATE groups SET version = version + 1
     WHERE id IN (SELECT group_id FROM group_members WHERE user_id = NEW.id);
    UPDATE oncall_roles SET version = version + 1
     WHERE supervisor_user_id = NEW.id
        OR id IN (SELECT oncall_role_id FROM oncall_schedules WHERE user_id = NEW.id);
    RETURN NULL;
END;
$$ LANGUAGE plpgsql;

-- a renamed group: the on-call roles that use it as membership group show the name
CREATE OR REPLACE FUNCTION usermgmt_bump_for_group_name() RETURNS trigger AS $$
BEGIN
    UPDATE oncall_roles SET version = version + 1 WHERE membership_group_id = NEW.id;
    RETURN NULL;
END;
$$ LANGUAGE plpgsql;

changeSet.sql:
CREATE TRIGGER users_row_version BEFORE UPDATE ON users FOR EACH ROW EXECUTE PROCEDURE usermgmt_bump_row_version();
CREATE TRIGGER groups_row_version BEFORE UPDATE ON groups FOR EACH ROW EXECUTE PROCEDURE usermgmt_bump_row_version();
CREATE TRIGGER oncall_roles_row_version BEFORE UPDATE ON oncall_roles FOR EACH ROW EXECUTE PROCEDURE usermgmt_bump_row_version();
CREATE TRIGGER security_roles_row_version BEFORE UPDATE ON security_roles FOR EACH ROW EXECUTE PROCEDURE usermgmt_bump_row_version();

CREATE TRIGGER user_contacts_bump_parent AFTER INSERT OR UPDATE OR DELETE ON user_contacts FOR EACH ROW EXECUTE PROCEDURE usermgmt_bump_parent('users', 'user_id');
CREATE TRIGGER user_duty_schedules_bump_parent AFTER INSERT OR UPDATE OR DELETE ON user_duty_schedules FOR EACH ROW EXECUTE PROCEDURE usermgmt_bump_parent('users', 'user_id');
CREATE TRIGGER user_security_roles_bump_parent AFTER INSERT OR UPDATE OR DELETE ON user_security_roles FOR EACH ROW EXECUTE PROCEDURE usermgmt_bump_parent('users', 'user_id');
CREATE TRIGGER group_members_bump_parent AFTER INSERT OR UPDATE OR DELETE ON group_members FOR EACH ROW EXECUTE PROCEDURE usermgmt_bump_parent('groups', 'group_id');
CREATE TRIGGER group_duty_schedules_bump_parent AFTER INSERT OR UPDATE OR DELETE ON group_duty_schedules FOR EACH ROW EXECUTE PROCEDURE usermgmt_bump_parent('groups', 'group_id');
CREATE TRIGGER oncall_schedules_bump_parent AFTER INSERT OR UPDATE OR DELETE ON oncall_schedules FOR EACH ROW EXECUTE PROCEDURE usermgmt_bump_parent('oncall_roles', 'oncall_role_id');
CREATE TRIGGER oncall_schedule_times_bump_parent AFTER INSERT OR UPDATE OR DELETE ON oncall_schedule_times FOR EACH ROW EXECUTE PROCEDURE usermgmt_bump_oncall_role_of_time();

-- Hibernate's UPDATE lists every column, so UPDATE OF alone would fire on every save: the WHEN clauses matter
CREATE TRIGGER users_username_bump AFTER UPDATE OF username ON users FOR EACH ROW WHEN (OLD.username IS DISTINCT FROM NEW.username) EXECUTE PROCEDURE usermgmt_bump_for_username();
CREATE TRIGGER groups_name_bump AFTER UPDATE OF name ON groups FOR EACH ROW WHEN (OLD.name IS DISTINCT FROM NEW.name) EXECUTE PROCEDURE usermgmt_bump_for_group_name();

rollback.sql:
DROP TRIGGER IF EXISTS users_row_version ON users;
DROP TRIGGER IF EXISTS groups_row_version ON groups;
DROP TRIGGER IF EXISTS oncall_roles_row_version ON oncall_roles;
DROP TRIGGER IF EXISTS security_roles_row_version ON security_roles;
DROP TRIGGER IF EXISTS user_contacts_bump_parent ON user_contacts;
DROP TRIGGER IF EXISTS user_duty_schedules_bump_parent ON user_duty_schedules;
DROP TRIGGER IF EXISTS user_security_roles_bump_parent ON user_security_roles;
DROP TRIGGER IF EXISTS group_members_bump_parent ON group_members;
DROP TRIGGER IF EXISTS group_duty_schedules_bump_parent ON group_duty_schedules;
DROP TRIGGER IF EXISTS oncall_schedules_bump_parent ON oncall_schedules;
DROP TRIGGER IF EXISTS oncall_schedule_times_bump_parent ON oncall_schedule_times;
DROP TRIGGER IF EXISTS users_username_bump ON users;
DROP TRIGGER IF EXISTS groups_name_bump ON groups;
DROP FUNCTION IF EXISTS usermgmt_bump_row_version();
DROP FUNCTION IF EXISTS usermgmt_bump_parent();
DROP FUNCTION IF EXISTS usermgmt_bump_oncall_role_of_time();
DROP FUNCTION IF EXISTS usermgmt_bump_for_username();
DROP FUNCTION IF EXISTS usermgmt_bump_for_group_name();

changeSet.createProcedure:
CREATE OR REPLACE FUNCTION usermgmt_increment_version() RETURNS trigger AS $$
BEGIN
    IF current_setting('usermgmt.category_group_bump', true) = 'on' THEN
        RETURN NULL;
    END IF;
    UPDATE usermgmt_version SET version = version + 1 WHERE name = TG_ARGV[0];
    RETURN NULL;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION usermgmt_bump_for_category_group() RETURNS trigger AS $$
BEGIN
    PERFORM 1 FROM usermgmt_version WHERE name = 'groups' FOR UPDATE;
    IF TG_OP = 'UPDATE' AND NEW IS NOT DISTINCT FROM OLD THEN
        RETURN NULL;
    END IF;
    PERFORM set_config('usermgmt.category_group_bump', 'on', true);
    IF TG_OP <> 'DELETE' THEN
        UPDATE groups SET version = version + 1 WHERE name = NEW.groupid;
    END IF;
    IF TG_OP <> 'INSERT' AND (TG_OP = 'DELETE' OR OLD.groupid IS DISTINCT FROM NEW.groupid) THEN
        UPDATE groups SET version = version + 1 WHERE name = OLD.groupid;
    END IF;
    PERFORM set_config('usermgmt.category_group_bump', 'off', true);
    RETURN NULL;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION usermgmt_lock_for_category_group() RETURNS trigger AS $$
BEGIN
    -- the order of UserMgmtVersionDao.lockAll(): users, then groups
    PERFORM 1 FROM usermgmt_version WHERE name = 'users' FOR UPDATE;
    PERFORM 1 FROM usermgmt_version WHERE name = 'groups' FOR UPDATE;
    RETURN NULL;
END;
$$ LANGUAGE plpgsql;

changeSet.sql:
CREATE TRIGGER category_group_lock_versions BEFORE INSERT OR UPDATE OR DELETE ON category_group FOR EACH STATEMENT EXECUTE PROCEDURE usermgmt_lock_for_category_group();
CREATE TRIGGER category_group_bump_group AFTER INSERT OR UPDATE OR DELETE ON category_group FOR EACH ROW EXECUTE PROCEDURE usermgmt_bump_for_category_group();
CREATE TRIGGER categories_lock_versions BEFORE DELETE ON categories FOR EACH STATEMENT EXECUTE PROCEDURE usermgmt_lock_for_category_group();

rollback.sql:
DROP TRIGGER IF EXISTS categories_lock_versions ON categories;
DROP TRIGGER IF EXISTS category_group_bump_group ON category_group;
DROP TRIGGER IF EXISTS category_group_lock_versions ON category_group;
DROP FUNCTION IF EXISTS usermgmt_bump_for_category_group();
DROP FUNCTION IF EXISTS usermgmt_lock_for_category_group();

rollback.createProcedure:
CREATE OR REPLACE FUNCTION usermgmt_increment_version() RETURNS trigger AS $$
BEGIN
    UPDATE usermgmt_version SET version = version + 1 WHERE name = TG_ARGV[0];
    RETURN NULL;
END;
$$ LANGUAGE plpgsql;
